INSERT INTO public.blog_seo (slug, title, description, image_url, page_type) VALUES
('how-to-offer-ev-charging-in-an-app', 'How to Offer EV Charging in an App: Definitive Guide | NetworkCore', 'How to offer EV charging in an app — without infrastructure. Native integration via API or iframe, public CPO tariffs, revenue per session, full compliance.', 'https://networkcore.org/images/blog/how-to-offer-ev-charging-in-an-app.jpg', 'blog'),
('ev-charging-as-a-service-platform', 'EV Charging as a Service Platform: What It Actually Means | NetworkCore', 'Most products called an EV charging as a service platform aren''t one. Here''s what the term should mean — and the structural conditions a real platform has to clear.', 'https://networkcore.org/images/blog/ev-charging-as-a-service-platform.jpg', 'blog'),
('monetising-in-car-charging', 'Monetising In-Car Charging: OEMs Should Run Demand, Not Networks | NetworkCore', 'OEMs own the most valuable asset in EV charging — the driver. Learn why monetising in-car charging works as a distribution strategy, not an infrastructure one.', 'https://networkcore.org/images/blog/monetising-in-car-charging.jpg', 'blog'),
('how-ev-charging-works-across-borders', 'How EV Charging Works Across Borders | NetworkCore', 'How EV charging works across borders, why roaming only solved the data layer, and why settlement, VAT, FX, and compliance still need infrastructure.', 'https://networkcore.org/images/blog/how-ev-charging-works-across-borders.png', 'blog'),
('ev-charging-orchestration-platform', 'EV Charging Orchestration Platform | NetworkCore', 'Why non-CPOs should stop licensing EV charging orchestration platforms and use a distribution channel instead.', 'https://networkcore.org/images/blog/ev-charging-orchestration-platform.png', 'blog'),
('ev-charging-transaction-platform', 'EV Charging Transaction Platform | NetworkCore', 'An EV charging transaction platform is purpose-built financial infrastructure for the full commercial lifecycle of every public charging session — settlement, FX, VAT, compliance.', 'https://networkcore.org/images/blog/ev-charging-transaction-platform.png', 'blog'),
('ev-charger-platform-vs-roaming-hub', 'EV Charger Platform vs Roaming Hub: What CPOs Need to Know | NetworkCore', 'EV charger platform vs roaming hub: how money moves, when CPOs get paid, and whether the platform brings real demand. The questions to ask before signing.', 'https://networkcore.org/images/blog/ev-charger-platform-vs-roaming-hub.jpg', 'blog'),
('ev-charging-vat-explained', 'EV Charging VAT Explained: Definitive Rate Reference 2026 | NetworkCore', 'EV charging VAT explained — country-by-country rates, fee-type breakdowns, and active legal disputes. Definitive 2026 reference for CPOs and Demand Partners.', 'https://networkcore.org/images/blog/ev-charging-vat-explained.jpg', 'blog'),
('offer-ev-charging-without-owning-chargers', 'Offer EV Charging Without Owning Chargers | NetworkCore', 'Any platform with demand can offer EV charging without owning chargers — earn on every session through one API integration with the right roaming partner.', 'https://networkcore.org/images/blog/offer-ev-charging-without-owning-chargers.png', 'blog'),
('embedded-mobility-services-for-fintechs', 'Embedded Mobility Services for Fintechs: EV Charging as a Service | NetworkCore', 'Embedded mobility services for fintechs turn EV charging into a native, revenue-generating product — no infrastructure, no balance sheet risk, settled within 48 hours.', 'https://networkcore.org/images/blog/embedded-mobility-services-for-fintechs.png', 'blog')
